use std::collections::HashSet;

fn solve(cafes: Vec<i8>) -> i8 {
    // We traverse from the end to record each value's last occurrence exactly once.
    // The last new value we encounter in this reverse traversal
    // is the one whose last occurrence index is minimal.
    let mut seen = HashSet::new();
    let mut result = cafes[0];
    for &c in cafes.iter().rev() {
        if seen.insert(c) {
            result = c;
        }
    }
    result
}

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Find the largest index where cafes[index] == cafe.
    // Since it's guaranteed to appear, unwrap is safe.
    cafes.iter().rposition(|&x| x == cafe).unwrap()
}

